test('refuses to merge unrelated histories during branch sync', function() {
    var commands = [];
    var pr = loadPullRequestHelper();

    var result = pr.syncBranchWithBase({
        branchName: 'feature/DMC-7',
        baseBranch: 'main',
        runCommand: function(command) {
