            // forward. Shared canonical list: js/common/gitStaging.js.
            runCmd({
                command: gitStaging.buildUntrackCommand()
            });
        } catch (cleanupErr) {
            console.warn('Could not remove tracked Copilot session cache before staging:', cleanupErr);
        }

