        { command: 'git merge-base origin/main HEAD', workingDirectory: 'repo' },
        { command: 'git merge-base origin/main HEAD', workingDirectory: 'repo' },
        { command: 'git status --porcelain --ignore-submodules=dirty', workingDirectory: 'repo' },
