```js
// gh-737: the merge bot links approved issues to PRs ONLY via 'Closes #N' in
// the PR body (or branch 'N-*'). Factory PRs built from response.md templates
// don't carry it → bot merges nothing. Guarantee the canonical line by
// construction: extract the trailing number from the ticket key (gh-737 → 737,
// PROJ-123 → 123) and prepend 'Closes #N' when the body lacks it. Idempotent;
// other keywords (Fixes/Part-of) never substitute — the pack emits canonical Closes.
function extractIssueNumber(ticketKey) {
    var m = /(\d+)\s*$/.exec(String(ticketKey || '').trim());
    return m ? m[1] : null;
}

