            // Fallback: build minimal shape from URL if the SCM response differs.
            var prNumber = null;
            if (prResult.prUrl) {
                var m = prResult.prUrl.match(/\/pull\/(\d+)$/);
                if (m) prNumber = parseInt(m[1], 10);
            }
            return { number: prNumber, html_url: prResult.prUrl, head: { ref: branchName } };
