test('syncs branch with base before publishing when behind', function() {
    var commands = [];
    var pr = loadPullRequestHelper();

    var result = pr.syncBranchWithBase({
        branchName: 'feature/DMC-4',
        baseBranch: 'main',
        workingDir: 'repo',
