    var num = extractIssueNumber(ticketKey);
    if (!num) return body;
    var text = String(body == null ? '' : body);
    if (new RegExp('Closes\\s+#?' + num + '\\b', 'i').test(text)) return text;
    return 'Closes #' + num + '\n' + text;
}
