{"newText":"// ── Closes line (gh-737) ────────────────────────────────────────────────────
// The merge bot (awf factory-merge-trigger) links approved issues to PRs ONLY
// via 'Closes #N' in the PR body (or branch 'N-*'). Factory-created PRs built
// from the response.md template carried no Closes line, so the bot reported
// 'no linked open PR' for every approved issue and merged nothing
// (merged=0 skipped=4, live fa 2026-10-05). Every PR the pack creates must
// therefore carry the canonical line by construction. Bot-side awf#19 also
// accepts Fixes/Part-of, but the pack still emits canonical Closes.
var CLOSES_LINE_KEYWORDS = ['Closes', 'Fixes', 'Part-of', 'Part of', 'Relates to', 'Refs'];

/**
 * Extracts the trailing issue number from a ticket key (gh-737 → '737',
 * PROJ-123 → '123'). Returns null when the key carries no digits.
 */
function extractIssueNumber(ticketKey) {
    var m = /(\d+)\s*$/.exec(String(ticketKey || '').trim());
    return m ? m[1] : null;
}

/**
 * Guarantees the body contains the canonical 'Closes #N' line for the ticket.
 * Idempotent: a body that already closes the same issue is left untouched.
 * Non-canonical keywords (Fixes/Part-of) never substitute — the pack emits
 * the canonical Closes the merge bot keys on. Keys without digits leave the
 * body unchanged.
 */
function ensureClosesLine(body, ticketKey) {
    var num = extractIssueNumber(ticketKey);
    if (!num) return body;

    var text = body === null || body === undefined ? '' : String(body);
    for (var i = 0; i < CLOSES_LINE_KEYWORDS.length; i++) {
        var kw = CLOSES_LINE_KEYWORDS[i];
        // Only the canonical 'Closes' is considered a duplicate; any other
        // keyword still gets the canonical line added on top.
        if (kw !== 'Closes') continue;
        if (new RegExp('\\b' + kw + '\\s+#?' + num + '\\b', 'i').test(text)) return text;
    }

    return 'Closes #' + num + '\n' + text;
}

// GitHub limits PR bodies to 65536 characters. Keep a safety margin so
// gh pr create does not fail on oversized bodies generated by agents.
var MAX_GH_PR_BODY_LENGTH = 60000;","oldText":"// GitHub limits PR bodies to 65536 characters. Keep a safety margin so
