        pushOutput.indexOf('error: failed to push') !== -1 ||
        pushOutput.indexOf('push declined') !== -1 ||
        pushOutput.indexOf('non-fast-forward') !== -1 ||
        pushOutput.indexOf('rejected') !== -1;

